package com.metabuild.modules.admin.messages.persistence;
import static com.metabuild.schema.platform.tables.MbInboxPublishOutbox.MB_INBOX_PUBLISH_OUTBOX;
import com.metabuild.admin.api.*;import com.metabuild.modules.admin.messages.application.InboxOutboxSignal;import com.metabuild.shared.kernel.UuidV7Generator;import java.util.*;import org.jooq.DSLContext;import org.springframework.transaction.support.*;
/** 在调用方业务事务内持久化 outbox；after-commit 只做无状态唤醒。 */
public final class JooqInboxPublisher implements InboxPublisher {private final DSLContext db;private final UuidV7Generator ids;private final InboxOutboxSignal signal;public JooqInboxPublisher(DSLContext db,UuidV7Generator ids,InboxOutboxSignal signal){this.db=db;this.ids=ids;this.signal=signal;}public PublishResult publish(Collection<InboxMessageCommand> commands){Set<String> queued=new LinkedHashSet<>(),rejected=new LinkedHashSet<>();for(var c:commands){if(!valid(c)){rejected.add(c==null?null:c.idempotencyKey());continue;}String category=normalize(c.category());db.insertInto(MB_INBOX_PUBLISH_OUTBOX,MB_INBOX_PUBLISH_OUTBOX.ID,MB_INBOX_PUBLISH_OUTBOX.RECIPIENT_USER_ID,MB_INBOX_PUBLISH_OUTBOX.IDEMPOTENCY_KEY,MB_INBOX_PUBLISH_OUTBOX.CATEGORY,MB_INBOX_PUBLISH_OUTBOX.TITLE,MB_INBOX_PUBLISH_OUTBOX.BODY,MB_INBOX_PUBLISH_OUTBOX.LINK).values(ids.generate(),c.recipientUserId(),c.idempotencyKey(),category,c.titleKey(),c.body(),c.link()).onConflict(MB_INBOX_PUBLISH_OUTBOX.RECIPIENT_USER_ID,MB_INBOX_PUBLISH_OUTBOX.IDEMPOTENCY_KEY).doNothing().execute();queued.add(c.idempotencyKey());}wakeAfterCommit();return new PublishResult(queued,rejected);}private void wakeAfterCommit(){if(TransactionSynchronizationManager.isActualTransactionActive()&&TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){signal.wake();}});else signal.wake();}private static boolean valid(InboxMessageCommand c){return c!=null&&c.idempotencyKey()!=null&&!c.idempotencyKey().isBlank()&&c.recipientUserId()!=null&&c.titleKey()!=null&&c.body()!=null;}private static String normalize(String c){return Set.of("approval","security","system").contains(c)?c:"system";}}
